import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {createReadStream,readFileSync,writeFileSync,mkdirSync} from "node:fs";
import {lstat,readdir,unlink,rmdir} from "node:fs/promises";
import {join,resolve,relative,isAbsolute} from "node:path";
const root=resolve(import.meta.dir,"../../../../../../../../../"),ticket=join(root,".🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️11/CLEAN-ARCHITECTURE-LAYERING-ENFORCEMENT"),output=join(ticket,"🗑️generated/controlled-cargo-callers"),storage=join(output,"snapshot-retirement-2"),[mode]=process.argv.slice(2),controller=new AbortController(),sha=(source:string)=>createHash("sha256").update(source).digest("hex"),epochs=[12,13];
mkdirSync(storage,{recursive:true});process.once("SIGINT",()=>controller.abort());process.once("SIGTERM",()=>controller.abort());
try{if(mode==="validate")await validate();else if(mode==="retire")await retire();else throw Error("Expected validate or retire");}catch(error){writeFileSync(join(storage,"refusal-"+mode+".json"),JSON.stringify({at:new Date().toISOString(),phase:controller.signal.aborted?"cancelled":"refused",message:String(error),atomic:false}));throw error;}
async function hash(path:string):Promise<string>{controller.signal.throwIfAborted();const stat=await lstat(path);assert.ok(stat.isFile()&&!stat.isSymbolicLink());const digest=createHash("sha256"),stream=createReadStream(path,{highWaterMark:262144,signal:controller.signal});for await(const bytes of stream){controller.signal.throwIfAborted();digest.update(bytes);}return digest.digest("hex");}
async function validate():Promise<void>{
 const journal:{epoch:number;frames:number;validatedBodies:number;inputs:{path:string;source:string;hash:string}[];snapshot:string;advanceBodies:{path:string;hash:string}[];bodyStats:{path:string;size:number;mtimeMs:number;ctimeMs:number;ino:number;dev:number}[]}[]=[],started=Date.now();let completed=0;
 for(const epoch of epochs){
  const directory=join(output,"current-origin-whole-test-"+epoch),snapshot=join(directory,"snapshot"),paths=[join(directory,"admission.json"),join(directory,"terminal.json"),directory+".json"],inputs=paths.map(path=>{const source=readFileSync(path,"utf8");return{path,source,hash:sha(source)}}),[admission,terminal,receipt]=inputs.map(row=>JSON.parse(row.source));
  assert.ok([137,143].includes(terminal.code));assert.equal(receipt.posts.length,admission.frames.length);assert.ok(receipt.posts.every(row=>row.sealed));assert.equal((await lstat(snapshot)).isSymbolicLink(),false);
  const bodyStats:{path:string;size:number;mtimeMs:number;ctimeMs:number;ino:number;dev:number}[]=[],bodies=new Map<string,string>();for(const frame of admission.frames){assert.ok(frame.fullBody.startsWith(directory+"/bodies/"));assert.match(frame.snapshotHash,/^[a-f0-9]{64}$/u);const previous=bodies.get(frame.fullBody);if(previous)assert.equal(previous,frame.snapshotHash);bodies.set(frame.fullBody,frame.snapshotHash);}
  for(const[path,expected]of bodies){assert.equal(await hash(path),expected,path);const stat=await lstat(path);bodyStats.push({path,size:stat.size,mtimeMs:stat.mtimeMs,ctimeMs:stat.ctimeMs,ino:stat.ino,dev:stat.dev});if(++completed%128===0){console.log("[DEBUG] snapshot custody bodies="+completed+" elapsedMs="+(Date.now()-started));await new Promise<void>(done=>setImmediate(done));}}
  const advanceBodies:{path:string;hash:string}[]=[];for(const frame of receipt.snapshotAdvances){const manifest=join(directory,"snapshot-advances",sha(frame.path)+".json"),source=readFileSync(manifest,"utf8"),advance=JSON.parse(source);inputs.push({path:manifest,source,hash:sha(source)});if(advance.afterBody){assert.ok(advance.afterBody.startsWith(directory+"/snapshot-advances/"));assert.equal(await hash(advance.afterBody),advance.afterHash);advanceBodies.push({path:advance.afterBody,hash:advance.afterHash});}}
  for(const input of inputs)assert.equal(sha(readFileSync(input.path,"utf8")),input.hash);
  journal.push({epoch,frames:admission.frames.length,validatedBodies:bodies.size,inputs:inputs.map(({path,hash})=>({path,hash})),snapshot,advanceBodies,bodyStats});
 }
 writeFileSync(join(storage,"validated.json"),JSON.stringify({at:new Date().toISOString(),phase:"validated",journal,sourceWrites:0,snapshotWrites:0}));console.log("[DEBUG] validated closed snapshot custody epochs=12,13 bodies="+completed);
}
async function retire():Promise<void>{
 const validationPath=join(storage,"validated.json"),validationSource=readFileSync(validationPath,"utf8"),validation=JSON.parse(validationSource);assert.equal(validation.phase,"validated");assert.deepEqual(validation.journal.map(row=>row.epoch),epochs);
 const intent=join(storage,"retirement.json");writeFileSync(intent,JSON.stringify({at:new Date().toISOString(),phase:"prepared",validation:{path:validationPath,hash:sha(validationSource)},paths:validation.journal.map(row=>row.snapshot),retained:["bodies","inputs.jsonl","admission.json","terminal.json","snapshot-advances","all logs","all reports","all authored inputs"],atomic:false}));let removed=0,bytes=0;
 const remove=async(path:string):Promise<void>=>{controller.signal.throwIfAborted();const stat=await lstat(path);if(stat.isDirectory()&&!stat.isSymbolicLink()){for(const entry of await readdir(path))await remove(join(path,entry));await rmdir(path);}else{bytes+=stat.size;await unlink(path);}if(++removed%512===0){console.log("[DEBUG] duplicate snapshot retirement entries="+removed+" bytes="+bytes);await new Promise<void>(done=>setImmediate(done));}};
 for(const row of validation.journal){assert.equal(row.snapshot,join(output,"current-origin-whole-test-"+row.epoch,"snapshot"));const local=relative(output,row.snapshot);assert.ok(!isAbsolute(local)&&!local.startsWith(".."));for(const input of row.inputs)assert.equal(sha(readFileSync(input.path,"utf8")),input.hash);for(const input of row.advanceBodies)assert.equal(await hash(input.path),input.hash);for(const input of row.bodyStats){const stat=await lstat(input.path);assert.deepEqual({path:input.path,size:stat.size,mtimeMs:stat.mtimeMs,ctimeMs:stat.ctimeMs,ino:stat.ino,dev:stat.dev},input);}await remove(row.snapshot);writeFileSync(intent,JSON.stringify({at:new Date().toISOString(),phase:"partial",completedEpoch:row.epoch,removed,logicalBytes:bytes,validation:{path:validationPath,hash:sha(validationSource)},atomic:false}));}
 assert.equal(readFileSync(validationPath,"utf8"),validationSource);writeFileSync(intent,JSON.stringify({at:new Date().toISOString(),phase:"completed",epochs,removed,logicalBytes:bytes,validation:{path:validationPath,hash:sha(validationSource)},sourceWrites:0,retainedSealedBodies:true,atomic:false}));console.log("[DEBUG] duplicate snapshot retirement completed entries="+removed+" logicalBytes="+bytes);
}
